arguments.command:
curl -sS -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name kind ofType { name kind } } } } } } }"}' 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name']=='documentUpdate':
        for a in f['args']:
            t=a['type']
            print(a['name'], t['name'], t['kind'], (t['ofType'] or {}).get('name'), (t['ofType'] or {}).get('kind'))
"

